SET local check_function_bodies = off;

CREATE TABLE "public"."story_reactions" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "story_id"   bigint                   NOT NULL,
  "profile_id" bigint                   NOT NULL,
  "reaction"   public.post_reaction     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "story_reactions_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."story_reactions"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."story_reactions" FROM "anon", "authenticated";

CREATE TABLE "public"."story_views" (
  "story_id"   bigint                   NOT NULL,
  "profile_id" bigint                   NOT NULL,
  "viewed_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "story_views_pkey" PRIMARY KEY (story_id, profile_id)
);

ALTER TABLE "public"."story_views"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."story_views" FROM "anon", "authenticated";

CREATE OR REPLACE FUNCTION private.story_audience_profile_id (
  p_story_id bigint
)
  RETURNS bigint
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  viewer_id bigint;
  author_id bigint;
begin
  if not private.can_read_story(p_story_id) then
    raise exception 'story not found' using errcode = 'P0002';
  end if;

  select profile.id
  into viewer_id
  from public.profiles as profile
  where profile.auth_user_id = auth.uid();

  select story.profile_id
  into author_id
  from public.stories as story
  where story.id = p_story_id;

  return nullif(viewer_id, author_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_story_viewers (
  p_story_id bigint
)
  RETURNS TABLE (
    pub_id      text,
    name        text,
    avatar_path text,
    viewed_at   timestamp with time zone,
    reactions   public.post_reaction[]
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not exists (
    select 1
    from public.stories as story
    join public.profiles as author
      on author.id = story.profile_id
    where story.id = p_story_id
      and author.auth_user_id = auth.uid()
      and author.status = 'accepted'
      and author.deleted_at is null
      and not private.profile_suspended(author.id)
  ) then
    raise exception 'story owner required' using errcode = '42501';
  end if;

  return query
  select
    viewer.pub_id,
    viewer.name,
    viewer.avatar_path,
    seen.viewed_at,
    coalesce(
      array_agg(reaction.reaction order by reaction.created_at, reaction.id)
        filter (where reaction.id is not null),
      array[]::public.post_reaction[]
    )
  from public.story_views as seen
  join public.profiles as viewer
    on viewer.id = seen.profile_id
    and viewer.status = 'accepted'
    and viewer.deleted_at is null
  left join public.story_reactions as reaction
    on reaction.story_id = seen.story_id
    and reaction.profile_id = seen.profile_id
  where seen.story_id = p_story_id
  group by viewer.id, seen.viewed_at
  order by greatest(seen.viewed_at, max(reaction.created_at)) desc, viewer.id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."list_story_viewers"(bigint) FROM PUBLIC, "anon", "service_role";

CREATE OR REPLACE FUNCTION public.mark_story_viewed (
  p_story_id bigint
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  viewer_id bigint := private.story_audience_profile_id(p_story_id);
begin
  if viewer_id is null then
    return;
  end if;

  insert into public.story_views (story_id, profile_id)
  values (p_story_id, viewer_id)
  on conflict do nothing;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."mark_story_viewed"(bigint) FROM PUBLIC, "anon", "service_role";

CREATE OR REPLACE FUNCTION public.send_story_reaction (
  p_story_id bigint,
  p_reaction public.post_reaction
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  viewer_id bigint := private.story_audience_profile_id(p_story_id);
  sent_count integer;
begin
  if viewer_id is null then
    raise exception 'cannot react to an own story' using errcode = '42501';
  end if;

  insert into public.story_views (story_id, profile_id)
  values (p_story_id, viewer_id)
  on conflict do nothing;

  -- 같은 사람이 동시에 보낸 반응이 상한을 함께 넘지 않도록 본 기록을 잠그고 센다.
  perform 1
  from public.story_views as seen
  where seen.story_id = p_story_id
    and seen.profile_id = viewer_id
  for update;

  select count(*)
  into sent_count
  from public.story_reactions as reaction
  where reaction.story_id = p_story_id
    and reaction.profile_id = viewer_id;

  if sent_count >= 30 then
    raise exception 'too many story reactions' using errcode = '54000';
  end if;

  insert into public.story_reactions (story_id, profile_id, reaction)
  values (p_story_id, viewer_id, p_reaction);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."send_story_reaction"(bigint, public.post_reaction) FROM PUBLIC, "anon", "service_role";

ALTER TABLE "public"."story_reactions"
  ADD CONSTRAINT "story_reactions_story_id_profile_id_fkey" FOREIGN KEY (story_id, profile_id) REFERENCES public.story_views(story_id, profile_id) ON DELETE CASCADE;

ALTER TABLE "public"."story_views"
  ADD CONSTRAINT "story_views_profile_id_fkey" FOREIGN KEY (profile_id) REFERENCES public.profiles(id) ON DELETE CASCADE;

ALTER TABLE "public"."story_views"
  ADD CONSTRAINT "story_views_story_id_fkey" FOREIGN KEY (story_id) REFERENCES public.stories(id) ON DELETE CASCADE;

CREATE INDEX story_reactions_sender_idx ON public.story_reactions USING btree (story_id, profile_id, created_at);

CREATE INDEX story_views_profile_idx ON public.story_views USING btree (profile_id);

CREATE POLICY "story_reactions_deny_direct_access" ON "public"."story_reactions"
  FOR ALL
  TO PUBLIC
  USING (false)
  WITH CHECK (false);

CREATE POLICY "story_views_deny_direct_access" ON "public"."story_views"
  FOR ALL
  TO PUBLIC
  USING (false)
  WITH CHECK (false);

REVOKE ALL ON FUNCTION "private"."story_audience_profile_id"(bigint) FROM PUBLIC;

