REVOKE ALL ON FUNCTION "public"."send_story_reaction"(bigint, public.post_reaction) FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."send_story_reaction"(bigint, public.post_reaction) TO "postgres";

