GRANT UPDATE ON SEQUENCE "public"."story_reactions_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."story_reactions_id_seq" FROM "authenticated";

GRANT UPDATE ON SEQUENCE "public"."story_reactions_id_seq" TO "authenticated";

